const points = [];
for (let i = 0; i < 5_000_000; i++) {
  points.push({ x: i, y: i * 2 });  // alloc + pointer store -> write barrier each time
}

function recordBarrier(stores) {
  // BUG: records young->old, but the Scavenger needs OLD objects that point
  // INTO young space as extra roots, i.e. old->young. The check is reversed.
  const remembered = [];
  for (const s of stores) {
    if (s.from === 'young' && s.to === 'old') remembered.push(s.id);
  }
  return remembered;
}

