// fires on every `obj.field = value` pointer store
function writeBarrier(obj, value, state) {
  // generational part
  if (obj.gen === 'old' && value.gen === 'young') {
    state.rememberedSet.add(obj.id);
  }

  // marking part (concurrent mark in progress)
  if (state.marking && obj.color === 'black') {
    value.color = 'grey';            // shade the target
  }
}
